-- Marked functional reconstruction, not a recovered original LINK2 action.
-- Observed Slaghammer joins the real door-guard fight after the introductory exchange.
-- Native AttackStart only: no quest/kill/item credit, fabricated death or timed kill.
SET @slaghammer_link2_concat=@@session.group_concat_max_len;SET SESSION group_concat_max_len=1048576;START TRANSACTION;
SET @slaghammer_link2_graph=(SELECT SHA2(COALESCE(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`entryorguid` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`source_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`id` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`link` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`Difficulties` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_phase_mask` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_chance` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_flags` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param5` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param5` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param6` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_x` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_y` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_z` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_o` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`comment` AS CHAR CHARACTER SET utf8mb4),'NULL')) ORDER BY `id` SEPARATOR '\n'),''),256) FROM smart_scripts WHERE entryorguid=101430 AND source_type=0 AND id<>2);
SET @slaghammer_link2_conditions=(SELECT SHA2(COALESCE(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`SourceTypeOrReferenceId` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`SourceGroup` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`SourceEntry` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`SourceId` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ElseGroup` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionTypeOrReference` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionTarget` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionValue1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionValue2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionValue3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`NegativeCondition` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ErrorTextId` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`Comment` AS CHAR CHARACTER SET utf8mb4),'NULL')) ORDER BY `SourceGroup`,`ElseGroup`,`ConditionTypeOrReference` SEPARATOR '\n'),''),256) FROM conditions WHERE SourceTypeOrReferenceId=22 AND SourceEntry=101430 AND SourceGroup<>3);
SET @slaghammer_link2_safe=(@slaghammer_link2_graph='a3c3f6ad5f57cc6824400112be9f11245e9bb3a7551ae8772fbb41c13080d8e4' AND @slaghammer_link2_conditions='c524d47d94bfccf7f22c3607aef2e261c48b831170a2c8378e0e0a955d0cca0e'
 AND (SELECT COUNT(*) FROM creature_template WHERE entry=101430 AND AIName='SmartAI' AND ScriptName='npc_slaghammer_handoff' AND faction=1665 AND unit_flags=768)=1
 AND (SELECT COUNT(*) FROM creature_template WHERE entry=101122 AND AIName='SmartAI' AND ScriptName='' AND faction=16)=1
 AND (SELECT COUNT(*) FROM instance_template WHERE map=1539 AND script='instance_silver_hand')=1
 AND NOT EXISTS(SELECT 1 FROM smart_scripts WHERE entryorguid=101430 AND source_type=0 AND id=2 AND NOT(`entryorguid` <=> 101430 AND `source_type` <=> 0 AND `id` <=> 2 AND `link` <=> 0 AND `Difficulties` <=> '' AND `event_type` <=> 61 AND `event_phase_mask` <=> 0 AND `event_chance` <=> 100 AND `event_flags` <=> 1 AND `event_param1` <=> 0 AND `event_param2` <=> 0 AND `event_param3` <=> 0 AND `event_param4` <=> 0 AND `event_param5` <=> 0 AND `action_type` <=> 49 AND `action_param1` <=> 0 AND `action_param2` <=> 0 AND `action_param3` <=> 0 AND `action_param4` <=> 0 AND `action_param5` <=> 0 AND `action_param6` <=> 0 AND `target_type` <=> 19 AND `target_param1` <=> 101122 AND `target_param2` <=> 50 AND `target_param3` <=> 0 AND `target_param4` <=> 0 AND `target_x` <=> 0 AND `target_y` <=> 0 AND `target_z` <=> 0 AND `target_o` <=> 0 AND `comment` <=> 'Reconstruction: after exposure Slaghammer fights the actual door Shadowcaster; original LINK2 payload not recovered'))
 AND NOT EXISTS(SELECT 1 FROM conditions c WHERE c.SourceTypeOrReferenceId=22 AND c.SourceEntry=101430 AND c.SourceGroup=3 AND NOT EXISTS(SELECT 1 FROM conditions base WHERE base.SourceTypeOrReferenceId=c.SourceTypeOrReferenceId AND base.SourceEntry=c.SourceEntry AND base.SourceGroup=2 AND base.SourceId=c.SourceId AND base.ElseGroup=c.ElseGroup AND base.ConditionTypeOrReference=c.ConditionTypeOrReference AND base.ConditionTarget=c.ConditionTarget AND base.ConditionValue1=c.ConditionValue1 AND base.ConditionValue2=c.ConditionValue2 AND base.ConditionValue3=c.ConditionValue3 AND base.NegativeCondition=c.NegativeCondition AND base.ErrorTextId=c.ErrorTextId AND base.ScriptName=c.ScriptName AND c.Comment=CONCAT('Slaghammer reconstructed combat: ',base.Comment))));
SET @slaghammer_link2_guard=IF(COALESCE(@slaghammer_link2_safe,0),'DO 0','SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''Slaghammer LINK2 graph/binding/conditions differ; review before updating''');PREPARE slaghammer_link2_guard FROM @slaghammer_link2_guard;EXECUTE slaghammer_link2_guard;DEALLOCATE PREPARE slaghammer_link2_guard;
INSERT INTO smart_scripts(`entryorguid`,`source_type`,`id`,`link`,`Difficulties`,`event_type`,`event_phase_mask`,`event_chance`,`event_flags`,`event_param1`,`event_param2`,`event_param3`,`event_param4`,`event_param5`,`action_type`,`action_param1`,`action_param2`,`action_param3`,`action_param4`,`action_param5`,`action_param6`,`target_type`,`target_param1`,`target_param2`,`target_param3`,`target_param4`,`target_x`,`target_y`,`target_z`,`target_o`,`comment`) SELECT 101430,0,2,0,'',61,0,100,1,0,0,0,0,0,49,0,0,0,0,0,0,19,101122,50,0,0,0,0,0,0,'Reconstruction: after exposure Slaghammer fights the actual door Shadowcaster; original LINK2 payload not recovered' WHERE @slaghammer_link2_safe AND NOT EXISTS(SELECT 1 FROM smart_scripts WHERE entryorguid=101430 AND source_type=0 AND id=2);
INSERT INTO conditions SELECT SourceTypeOrReferenceId,3,SourceEntry,SourceId,ElseGroup,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,NegativeCondition,ErrorTextId,ScriptName,CONCAT('Slaghammer reconstructed combat: ',Comment) FROM conditions base WHERE @slaghammer_link2_safe AND SourceTypeOrReferenceId=22 AND SourceGroup=2 AND SourceEntry=101430 AND NOT EXISTS(SELECT 1 FROM conditions c WHERE c.SourceTypeOrReferenceId=22 AND c.SourceGroup=3 AND c.SourceEntry=101430 AND c.SourceId=base.SourceId AND c.ElseGroup=base.ElseGroup AND c.ConditionTypeOrReference=base.ConditionTypeOrReference);
COMMIT;SET SESSION group_concat_max_len=@slaghammer_link2_concat;
